import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { TRPCClientError } from '@trpc/client'

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // 默认 0 是绝大多数重复请求的根源，30 秒是通用起点
      // 强实时性数据（余额、库存）单独在调用处覆盖为 0
      staleTime: 30_000,
      gcTime: 5 * 60_000,
      // 对确定性错误不重试：重试 401 只会多三次失败请求
      retry: (failureCount, error) => {
        if (error instanceof TRPCClientError) {
          const code = error.data?.code
          if (code === 'UNAUTHORIZED' || code === 'FORBIDDEN' || code === 'NOT_FOUND') return false
          if (code === 'BAD_REQUEST') return false
        }
        return failureCount < 2
      },
      // 表单页频繁切标签时不希望输入区被后台刷新打断
      refetchOnWindowFocus: true,
    },
    mutations: {
      // mutation 默认不重试，这是对的：写操作重试需要幂等保证
      retry: 0,
    },
  },
}) 一条 query 的状态流转 这张图里最该记住的是 inactive -->

服务治理的三块基础设施：注册发现、配置、网关 - 资深码农 ~$ 资深码农 编程 数据库 接口 架构 运维 可观测 前端 工具 AI 生活 主页 / 架构与分布式 / 配置中心与服务发现 服务治理的三块基础设施：注册发现、配置、网关 🏷️ 配置中心 本篇是专题主干，只讲三者的共性、边界与可用性设计 ，具体机制分别在三篇子文里展开：服务端存储模型与推送实现见 配置中心的服务端机制与选型 ，注册发现的健康检查与摘除延迟见 服务注册发现的机制与故障模式 ，网关的数据面实现与部署形态见 网关的数据面实现与部署形态 。应用侧怎么用配置（配置四分类、能否热更新的判断、两阶段变更）见 微服务配置中心的应用侧实践 ，网关该放什么不该放什么见 API 网关的责任边界 ，Nginx 的请求处理阶段与限流形态见 Nginx 深入 。 三块基础设施其实是同一种架构 很多人把注册中心、配置中心、网关当成三门独立技术来学，结果是每换一个组件就要重新踩一遍坑。它们的内部结构其实完全同构： 一个保存权威数据的控制面，一个在请求路径上真正干活的数据面，中间是一条把变更同步过去的传播链路 。注册中心的权威数据是实例列表，配置中心的是配置版本，网关的是路由与插件规则，仅此而已。 这张图里最值得注意的是： 业务请求从来不穿过控制面 。控制面只与数据面的后台线程通信，请求路径上读到的永远是进程内存里的副本。这一条是后面所有可用性结论的地基，也是判断一个治理组件用得对不对的第一道检查。 共同特征 注册发现 配置中心 网关 权威数据 服务名到实例地址与元数据的映射 命名空间下的配置项与版本 路由规则、upstream、插件参数 数据面缓存形式 SDK 内存列表加磁盘快照 SDK 内存值加本地快照文件 worker 内存或共享内存中的路由表 写入频率 高：扩缩容、滚动更新、心跳状态变更 极低：一天几次到几十次 低：发布时集中变更 变更传播延迟 1 到 30 秒，取决于推送与缓存刷新 长轮询约 1 秒，定时拉取等于周期 xDS 秒级，reload 取决于发布流程 可容忍的数据陈旧 可容忍，本来就要靠重试兜底 部分可容忍，但灰度期间要求可控 不可长期陈旧，路由错会直接 502 控制面挂掉时数据面行为 继续用最后有效列表 继续用最后有效配置 继续按内存路由表转发 合适的一致性取向 AP 偏 CP：写要准，读可缓存 控制面偏 CP，数据面最终一致 缺了哪一块会发生什么 三块基础设施不是「架构好看」才加的，每一块都对应一个没有它就绕不过去的具体痛点。下表是常见的真实绕法，以及绕法后来一定会付出的代价。 缺失项 直接后果 团队实际会怎么绕 绕法的代价 没有注册发现 调用方不知道被调方的实例地址 把 IP 写死在配置里，或挂一个内网 LB，或用 DNS 轮询 扩缩容要改配置重发布；DNS 有缓存 TTL，摘除比注册中心还慢；LB 多一跳且看不到实例级指标 没有配置中心 调一个超时时间、开一个开关都要走发布流程 参数写进配置文件随镜像一起发布 止损时间被发布耗时绑定，一次回滚从半分钟变成十几分钟；参数散落在各服务仓库里无人能全局审计 没有网关 认证、限流、审计每个服务自己实现一遍 抽一个公共 SDK，或者让前端直连各服务 SDK 升级要所有服务配合发布，多语言要写多套；没有统一入口就没有统一的流量画像和一键封禁能力 三块都有但各自为政 网关不知道实例列表，配置不影响路由 网关里再维护一份静态 upstream 实例变更后网关继续打到死实例，出现「业务内部调用正常，从外部进来就 502」的诡异现象 核心要求：基础设施挂了，业务也要能继续跑 这三个组件有一个共同的危险属性： 全站都依赖它们 。一个业务服务挂了影响一个功能，注册中心挂了可能影响所有调用。既然无法把它们做成永不故障，唯一正确的设计方向就是让业务对它们保持弱依赖。落地下来只有三条，但很少有团队三条都做到。 ✅ 弱依赖的三条硬要求 第一， 本地缓存加启动兜底 ：拿到的数据必须落盘，进程冷启动时若控制面不可达就读快照，绝不因为拉不到数据而退出。第二， 控制面故障时数据面继续用最后有效值 ，不要把「拉取失败」误当成「数据被删除」，这是清空实例列表引发全站雪崩的典型成因。第三， 绝不在请求路径上同步调用控制面 ，所有远程交互都放在后台线程。 注意后半段：弱依赖不是没有代价，代价是 故障期间数据面会持有脏数据 。所以「本地缓存兜底」和「客户端侧的失败摘除、重试、熔断」是一套组合拳，只做前者会把问题从「全站不可发现」换成「持续打到死实例」。重试策略与熔断阈值见 熔断与重试 。 // 三块基础设施的客户端都该长这样：内存副本 + 快照兜底 + 后台刷新
