第一个 Terraform 项目与日常工作流 - 资深码农 ~$ 资深码农 编程 数据库 接口 架构 运维 可观测 前端 工具 AI 生活 主页 / 运维与云原生 / IaC 核心模型与工程纪律：声明式、状态与漂移 / Terraform 入门与 HCL 语法 第一个 Terraform 项目与日常工作流 🏷️ IaC 这篇是动手篇：把第一个能跑的项目搭出来，并把日常会反复用到的命令、语法和排错手段过一遍。声明式模型、漂移治理、协作纪律那些「为什么」在同专题的主干篇里讲；状态后端与加锁的配置细节详见站内 Terraform 状态管理篇；module 怎么设计、怎么做版本管理详见站内 Module 与最佳实践篇，本文只在需要时提一句。 最小可用项目的结构 一个目录下所有 .tf 文件会被合并解析，文件名对工具没有任何语义—— 拆文件纯粹是给人看的 。但这个约定收益很大：评审时能立刻看出改的是资源、是输入契约还是版本约束；合并冲突也少得多，因为不同人改的往往不是同一类东西。 文件 放什么 不要放什么 为什么单独拆 versions.tf required_version、required_providers、provider 块 业务资源 版本约束是全局前提，改它影响所有人，单独一个文件便于盯 main.tf resource、module、data、locals 硬编码的账号 ID、环境专属取值 这是评审的主战场，其他噪音越少越好 variables.tf variable 声明，带 type、description、validation 具体取值 它是这个根模块或 module 的对外契约，等同接口定义 outputs.tf 下游或其他项目需要的 id、地址、名称 敏感明文（如口令） 输出是给外部消费的，和内部实现分开才能稳定演进 terraform.tfvars 本环境的具体取值 任何密钥（会进 git 历史） 取值随环境变，与代码解耦；生产取值建议按环境目录分开放 一份能直接跑的最小示例 下面这套配置创建一个 VPC、两个可用区的子网、一个安全组和一台实例，带变量与输出。它刻意用了 for_each 、 data 源、 validation 、 default_tags ，这些都是日常真正会用到的写法。 # ---------- versions.tf ----------
terraform {
  # 限定 CLI 大版本，避免同事用差别过大的版本产生不兼容的状态
  required_version = ">= 1.6.0, < 2.0.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
      # 波浪号加大于号只允许最右一位递增：这里放行 5.60.x 到 5.x，
      # 但不会跳到 6.x。大版本升级必须单独提 PR 并看 plan
      version = "~> 5.60"
    }
  }
}

provider "aws" {
  region = var.region

  # 给所有资源自动打标：排查时能一眼分清哪些是 IaC 管的
  default_tags {
    tags = {
      Env       = var.env
      ManagedBy = "terraform"
      Repo      = "infra-demo"
    }
  }
}

# ---------- variables.tf ----------
variable "region" {
  type        = string
  description = "资源创建的地域"
}

variable "env" {
  type        = string
  description = "环境标识，会进资源名与标签"

  # validation 在 plan 之前就报错，比 apply 到一半失败便宜得多
  validation {
    condition     = contains(["dev", "staging", "prod"], var.env)
    error_message = "env 只能是 dev staging 或 prod。"
  }
}

variable "vpc_cidr" {
  type    = string
  default = "10.20.0.0/16"
}

