func GroupBy[T any, K comparable](items []T, keyFn func(T) K) map[K][]T {
    out := make(map[K][]T, len(items)/4) // 预估分组数，减少 rehash
    for _, it := range items {
        k := keyFn(it)
        out[k] = append(out[k], it) // 对 nil 切片 append 是合法的，不必先判断存在
    }
    return out
}

